export function NotificationCentre({
  heading = "{{heading}}",
  unreadCount = {{unreadCount}},
  accent = "{{accent}}",
  filter = "{{filter}}",
  showMarkAllRead = {{showMarkAllRead}},
}) {
  const tab = (value, label) => (
    <button type="button" key={value} style={{ background: filter === value ? accent : "#fff", borderColor: filter === value ? "transparent" : "#24143020", border: "1px solid", borderRadius: 999, padding: "4px 10px", font: "inherit", fontSize: 11, fontWeight: 600, cursor: "pointer" }}>{label}</button>
  );
  const items = [
    { unread: true, line: <><strong>Priya Nair</strong> mentioned you in the roadmap</>, time: "2026-08-18T14:32:00", label: "2:32 PM" },
    { unread: false, line: "Weekly digest is ready", time: "2026-08-18T09:00:00", label: "9:00 AM" },
    { unread: false, line: "Build #482 succeeded", time: "2026-08-17T18:12:00", label: "Yesterday" },
  ];
  return (
    <section aria-label={heading} style={{ fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430", background: "#FAF7F2", maxWidth: 320, width: 320, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, marginBottom: 10 }}>
        <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700, display: "flex", alignItems: "center", gap: 6 }}>
          {heading} <span aria-hidden="true" style={{ background: accent, borderRadius: 999, padding: "1px 7px", fontSize: 11 }}>{unreadCount}</span>
          <span style={{ position: "absolute", width: 1, height: 1, overflow: "hidden" }}>, {unreadCount} unread</span>
        </h3>
        {showMarkAllRead && <button type="button" style={{ background: "transparent", border: "none", color: "#241430a0", font: "inherit", fontSize: 11, textDecoration: "underline", cursor: "pointer", flexShrink: 0 }}>Mark all as read</button>}
      </div>
      <div role="group" aria-label="Filter notifications" style={{ display: "flex", gap: 6, marginBottom: 10 }}>
        {tab("all", "All")}
        {tab("unread", "Unread")}
        {tab("mentions", "Mentions")}
      </div>
      <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
        {items.map((item, i) => (
          <li key={i} style={{ padding: "9px 10px", borderRadius: 8, marginBottom: i === items.length - 1 ? 0 : 6, background: "#fff", boxShadow: item.unread ? `inset 3px 0 0 ${accent}` : "none" }}>
            <p style={{ margin: 0 }}>{item.line}</p>
            <time style={{ display: "block", marginTop: 3, fontSize: 11, color: "#24143080" }} dateTime={item.time}>{item.label}</time>
          </li>
        ))}
      </ul>
    </section>
  );
}
